        return 0;
    }
    int sum = 1;
    for (int divisor = 2; divisor <= value / divisor; ++divisor) {
        if (value % divisor != 0) {
            continue;
        }
        sum += divisor;
        const int paired = value / divisor;
        if (paired != divisor) {
            sum += paired;
        }
    }
    return sum;
}

